// Si llega desde el comando "revisar", corre aunque el monitoreo esté en pausa
const entrada = $input.first().json;
const pedido = entrada.revisar === true;
if ($getWorkflowStaticData('global').__pausado && !pedido) return [];

// ==========================================
// EDITA AQUI la lista de servicios a vigilar
// ==========================================
const servicios = [
  { nombre: 'Sitio web', url: 'https://ejemplo.com' },
  { nombre: 'API interna', url: 'https://api.ejemplo.com/health' },
  { nombre: 'Panel admin', url: 'http://192.168.1.50:8080' },
];

return servicios.map(s => ({ json: { ...s, pedido, responderA: entrada.responderA ?? null } }));

// Junta el resultado HTTP con el nombre y URL del servicio original
const origen = $('Lista de servicios').itemMatching(0).json;
const pedido = origen.pedido === true;          // vino del comando "revisar"
const responderA = origen.responderA ?? null;

const resultados = $input.all().map((item, i) => {
  const servicio = $('Lista de servicios').itemMatching(i).json;
  const r = item.json;
  let codigo = null;
  let detalle;
  if (r.error) {
    const e = r.error;
    detalle = typeof e === 'string' ? e : (e.code || e.message || JSON.stringify(e));
  } else {
    codigo = r.statusCode ?? null;
    detalle = `código ${codigo}`;
  }
  return {
    json: {
      nombre: servicio.nombre,
      url: servicio.url,
      codigo,
      detalle,
      hayError: Boolean(r.error),
      directo: false,
    },
  };
});

function resumen(u, pausado) {
  if (!u) return '📋 Todavía no hay ninguna revisión guardada.';
  const fecha = new Date(u.fecha).toLocaleString('es-MX', { timeZone: 'America/Chihuahua', dateStyle: 'short', timeStyle: 'short' });
  const lineas = [`📋 Estado de servicios (${fecha})`];
  if (u.redCaida) lineas.push('⚠️ En esa revisión no hubo red: ningún servicio respondió.');
  for (const s of u.servicios) lineas.push(`${s.ok ? '🟢' : '🔴'} ${s.nombre}: ${s.detalle}`);
  if (pausado) lineas.push('⏸️ El monitoreo automático está en pausa.');
  return lineas.join('\n');
}

const directo = (mensaje, destino = null) => ({ json: { directo: true, mensaje, responderA: destino } });
const estado = $getWorkflowStaticData('global');

// Regla de red local: si TODOS los servicios (2 o más) fallaron sin respuesta HTTP
// (DNS, sin red, timeout), casi seguro el problema es de esta máquina, no de los servicios.
// En ese caso no se toca el estado de cada servicio y se manda un solo aviso.
const redCaida = resultados.length >= 2 && resultados.every(r => r.json.hayError);

// Guarda la última revisión para el comando "estado"
estado.__ultimo = {
  fecha: new Date().toISOString(),
  redCaida,
  servicios: resultados.map(({ json: s }) => ({
    nombre: s.nombre,
    ok: !s.hayError && s.codigo >= 200 && s.codigo < 300,
    detalle: s.detalle,
  })),
};

const salida = [];
if (redCaida) {
  const errores = [...new Set(resultados.map(r => r.json.detalle))].join(', ');
  const aviso = `⚠️ Posible problema de red local: ningún servicio respondió (${errores}). No se cambió el estado de los servicios.`;
  if (estado.__redLocal !== 'caida') {
    estado.__redLocal = 'caida';
    salida.push(directo(aviso));
  } else if (pedido) {
    salida.push(directo(aviso, responderA));
  }
  return salida;
}

if (estado.__redLocal === 'caida') {
  estado.__redLocal = 'ok';
  salida.push(directo('✅ Red local recuperada: los servicios vuelven a responder.'));
}
if (pedido) salida.push(directo(resumen(estado.__ultimo, estado.__pausado), responderA));

return [...salida, ...resultados];

// Solo deja pasar los servicios que ANTES estaban arriba (o que nunca se habían revisado)
// Nota: el Static Data solo se guarda en ejecuciones de produccion (flujo activo)
const estado = $getWorkflowStaticData('global');
const salida = [];
for (const item of $input.all()) {
  const { nombre, url, detalle } = item.json;
  if (estado[url] !== 'caido') {
    salida.push({ json: { ...item.json, mensaje: `🔴 ${nombre} caído: ${url} (${detalle})` } });
  }
  estado[url] = 'caido';
}
return salida;

// Solo deja pasar los servicios que ANTES estaban caidos
const estado = $getWorkflowStaticData('global');
const salida = [];
for (const item of $input.all()) {
  const { nombre, url, detalle } = item.json;
  if (estado[url] === 'caido') {
    salida.push({ json: { ...item.json, mensaje: `🟢 ${nombre} recuperado: ${url} (${detalle})` } });
  }
  estado[url] = 'arriba';
}
return salida;

// Atiende los comandos que llegan desde el flujo "Receptor de comandos Signal"
const estado = $getWorkflowStaticData('global');
const { comando, responderA } = $input.first().json;

function resumen(u, pausado) {
  if (!u) return '📋 Todavía no hay ninguna revisión guardada.';
  const fecha = new Date(u.fecha).toLocaleString('es-MX', { timeZone: 'America/Chihuahua', dateStyle: 'short', timeStyle: 'short' });
  const lineas = [`📋 Estado de servicios (${fecha})`];
  if (u.redCaida) lineas.push('⚠️ En esa revisión no hubo red: ningún servicio respondió.');
  for (const s of u.servicios) lineas.push(`${s.ok ? '🟢' : '🔴'} ${s.nombre}: ${s.detalle}`);
  if (pausado) lineas.push('⏸️ El monitoreo automático está en pausa.');
  return lineas.join('\n');
}

let mensaje;
switch (comando) {
  case 'revisar':
    return [{ json: { revisar: true, responderA } }];
  case 'estado':
    mensaje = resumen(estado.__ultimo, estado.__pausado);
    break;
  case 'pausar':
    estado.__pausado = true;
    mensaje = '⏸️ Monitoreo pausado. No habrá revisiones automáticas ni alertas hasta que escribas "reanudar". "revisar" sigue funcionando.';
    break;
  case 'reanudar':
    estado.__pausado = false;
    mensaje = '▶️ Monitoreo reanudado. La siguiente revisión automática es en menos de 5 minutos.';
    break;
  default:
    mensaje = '🤖 Comandos (escríbelos en tu Nota personal):\nestado: último resultado de cada servicio\nrevisar: revisa todo ahora mismo\npausar: detiene las revisiones automáticas y alertas\nreanudar: las vuelve a activar\nayuda: esta lista';
}
return [{ json: { revisar: false, mensaje, responderA } }];
